## 路由配置

**属性路由**（推荐）：
```csharp
[ApiController]
[Route("api/[controller]")]
public class UsersController : ControllerBase
{
    [HttpGet]
    public IActionResult GetAll() { }

    [HttpGet("{id}")]
    public IActionResult GetById(int id) { }

    [HttpPost]
    public IActionResult Create([FromBody] UserDto user) { }

    [HttpPut("{id}")]
    public IActionResult Update(int id, [FromBody] UserDto user) { }

    [HttpDelete("{id}")]
    public IActionResult Delete(int id) { }
}
```

**路由约束**：
```csharp
[HttpGet("{id:int}")]
[HttpGet("{id:int:min(1)}")]
[HttpGet("{name:alpha}")]
[HttpGet("{date:datetime}")]
```

**路由参数绑定**：
- `[FromRoute]`：从 URL 路径获取
- `[FromQuery]`：从查询字符串获取
- `[FromBody]`：从请求体获取
- `[FromHeader]`：从请求头获取
- `[FromForm]`：从表单数据获取


## 模型绑定

ASP.NET Core 自动将请求数据绑定到操作参数：
```csharp
// JSON 请求体
[HttpPost]
public IActionResult Create([FromBody] CreateUserRequest request)
{
    // 自动反序列化 JSON
}

// 查询参数
[HttpGet]
public IActionResult Search([FromQuery] string keyword, [FromQuery] int page = 1)
{
    // 从查询字符串绑定
}

// 路由参数
[HttpGet("{id}")]
public IActionResult GetById([FromRoute] int id)
{
    // 从 URL 路径绑定
}
```

## 模型验证

使用数据注解进行验证：
```csharp
public class CreateUserRequest
{
    [Required(ErrorMessage = "用户名不能为空")]
    [StringLength(50, MinimumLength = 3)]
    public string Username { get; set; }

    [Required]
    [EmailAddress]
    public string Email { get; set; }

    [Required]
    [StringLength(100, MinimumLength = 6)]
    public string Password { get; set; }

    [Range(1, 150)]
    public int Age { get; set; }
}

// 控制器自动验证
[ApiController] // 自动验证模型
public class UsersController : ControllerBase
{
    [HttpPost]
    public IActionResult Create([FromBody] CreateUserRequest request)
    {
        // 如果验证失败，自动返回 400
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }
        // 处理请求
    }
}
```

**自定义验证**：
```csharp
public class UserValidator : AbstractValidator<CreateUserRequest>
{
    public UserValidator()
    {
        RuleFor(x => x.Username)
            .NotEmpty()
            .MinimumLength(3)
            .MustAsync(async (username, ct) => await IsUsernameUnique(username))
            .WithMessage("用户名已存在");
    }
}
```


## 响应格式

**统一响应格式**：
```csharp
public class ApiResponse<T>
{
    public int Code { get; set; }
    public string Message { get; set; }
    public T Data { get; set; }
    public object Errors { get; set; }
}

// 成功响应
return Ok(new ApiResponse<UserDto>
{
    Code = 200,
    Message = "成功",
    Data = userDto
});

// 错误响应
return BadRequest(new ApiResponse<object>
{
    Code = 400,
    Message = "验证失败",
    Errors = ModelState.ToDictionary(
        kvp => kvp.Key,
        kvp => kvp.Value.Errors.Select(e => e.ErrorMessage))
});
```


## 最佳实践

1. **版本控制**：使用 URL 或 Header 进行版本控制
2. **分页**：大数据集使用分页
3. **过滤排序**：支持查询参数过滤和排序
4. **HATEOAS**：在响应中包含相关链接
5. **限流**：防止 API 被滥用

using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using Microsoft.AspNetCore.Mvc;

namespace WebApiDesignDemo
{
    // 请求模型
    public class CreateProductRequest
    {
        [Required(ErrorMessage = "产品名称不能为空")]
        [StringLength(100, MinimumLength = 2)]
        public string Name { get; set; }

        [StringLength(500)]
        public string Description { get; set; }

        [Required]
        [Range(0.01, 100000)]
        public decimal Price { get; set; }

        [Required]
        [Range(0, 10000)]
        public int Stock { get; set; }

        [Required]
        [StringLength(50)]
        public string Category { get; set; }
    }

    public class UpdateProductRequest
    {
        [StringLength(100, MinimumLength = 2)]
        public string Name { get; set; }

        [StringLength(500)]
        public string Description { get; set; }

        [Range(0.01, 100000)]
        public decimal? Price { get; set; }

        [Range(0, 10000)]
        public int? Stock { get; set; }
    }

    // 响应模型
    public class ProductResponse
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Description { get; set; }
        public decimal Price { get; set; }
        public int Stock { get; set; }
        public string Category { get; set; }
        public DateTime CreatedAt { get; set; }
        public DateTime? UpdatedAt { get; set; }
    }

    public class ApiResponse<T>
    {
        public int Code { get; set; }
        public string Message { get; set; }
        public T Data { get; set; }
        public object Errors { get; set; }

        public static ApiResponse<T> Success(T data, string message = "成功")
        {
            return new ApiResponse<T>
            {
                Code = 200,
                Message = message,
                Data = data
            };
        }

        public static ApiResponse<T> Error(int code, string message, object errors = null)
        {
            return new ApiResponse<T>
            {
                Code = code,
                Message = message,
                Errors = errors
            };
        }
    }

    // 查询参数
    public class ProductQueryParameters
    {
        public string Category { get; set; }
        public decimal? MinPrice { get; set; }
        public decimal? MaxPrice { get; set; }
        public string Search { get; set; }
        public string SortBy { get; set; } = "Name";
        public bool Descending { get; set; }
        public int Page { get; set; } = 1;
        public int PageSize { get; set; } = 10;
    }

    // 控制器
    [ApiController]
    [Route("api/[controller]")]
    [Produces("application/json")]
    public class ProductsController : ControllerBase
    {
        private static readonly List<ProductResponse> Products = new();
        private static int _nextId = 1;

        /// <summary>
        /// 获取产品列表
        /// </summary>
        [HttpGet]
        [ProducesResponseType(typeof(ApiResponse<IEnumerable<ProductResponse>>), 200)]
        public IActionResult GetAll([FromQuery] ProductQueryParameters query)
        {
            var filtered = Products.AsQueryable();

            // 过滤
            if (!string.IsNullOrEmpty(query.Category))
                filtered = filtered.Where(p => p.Category == query.Category);

            if (query.MinPrice.HasValue)
                filtered = filtered.Where(p => p.Price >= query.MinPrice.Value);

            if (query.MaxPrice.HasValue)
                filtered = filtered.Where(p => p.Price <= query.MaxPrice.Value);

            if (!string.IsNullOrEmpty(query.Search))
                filtered = filtered.Where(p => p.Name.Contains(query.Search) ||
                                               p.Description.Contains(query.Search));

            // 排序
            filtered = query.SortBy?.ToLower() switch
            {
                "price" => query.Descending
                    ? filtered.OrderByDescending(p => p.Price)
                    : filtered.OrderBy(p => p.Price),
                "name" => query.Descending
                    ? filtered.OrderByDescending(p => p.Name)
                    : filtered.OrderBy(p => p.Name),
                _ => filtered.OrderBy(p => p.Name)
            };

            // 分页
            var paged = filtered
                .Skip((query.Page - 1) * query.PageSize)
                .Take(query.PageSize)
                .ToList();

            return Ok(ApiResponse<IEnumerable<ProductResponse>>.Success(paged));
        }

        /// <summary>
        /// 获取特定产品
        /// </summary>
        [HttpGet("{id:int:min(1)}")]
        [ProducesResponseType(typeof(ApiResponse<ProductResponse>), 200)]
        [ProducesResponseType(404)]
        public IActionResult GetById([FromRoute] int id)
        {
            var product = Products.FirstOrDefault(p => p.Id == id);
            if (product == null)
            {
                return NotFound(ApiResponse<ProductResponse>.Error(404, "产品不存在"));
            }
            return Ok(ApiResponse<ProductResponse>.Success(product));
        }

        /// <summary>
        /// 创建产品
        /// </summary>
        [HttpPost]
        [ProducesResponseType(typeof(ApiResponse<ProductResponse>), 201)]
        [ProducesResponseType(400)]
        public IActionResult Create([FromBody] CreateProductRequest request)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ApiResponse<ProductResponse>.Error(400, "验证失败",
                    ModelState.ToDictionary(
                        kvp => kvp.Key,
                        kvp => kvp.Value.Errors.Select(e => e.ErrorMessage))));
            }

            var product = new ProductResponse
            {
                Id = _nextId++,
                Name = request.Name,
                Description = request.Description,
                Price = request.Price,
                Stock = request.Stock,
                Category = request.Category,
                CreatedAt = DateTime.UtcNow
            };

            Products.Add(product);

            return CreatedAtAction(
                nameof(GetById),
                new { id = product.Id },
                ApiResponse<ProductResponse>.Success(product, "创建成功"));
        }

        /// <summary>
        /// 更新产品
        /// </summary>
        [HttpPut("{id}")]
        [ProducesResponseType(typeof(ApiResponse<ProductResponse>), 200)]
        [ProducesResponseType(404)]
        public IActionResult Update([FromRoute] int id, [FromBody] UpdateProductRequest request)
        {
            var product = Products.FirstOrDefault(p => p.Id == id);
            if (product == null)
            {
                return NotFound(ApiResponse<ProductResponse>.Error(404, "产品不存在"));
            }

            if (request.Name != null) product.Name = request.Name;
            if (request.Description != null) product.Description = request.Description;
            if (request.Price.HasValue) product.Price = request.Price.Value;
            if (request.Stock.HasValue) product.Stock = request.Stock.Value;
            product.UpdatedAt = DateTime.UtcNow;

            return Ok(ApiResponse<ProductResponse>.Success(product, "更新成功"));
        }

        /// <summary>
        /// 删除产品
        /// </summary>
        [HttpDelete("{id}")]
        [ProducesResponseType(204)]
        [ProducesResponseType(404)]
        public IActionResult Delete([FromRoute] int id)
        {
            var product = Products.FirstOrDefault(p => p.Id == id);
            if (product == null)
            {
                return NotFound(ApiResponse<object>.Error(404, "产品不存在"));
            }

            Products.Remove(product);
            return NoContent();
        }
    }

    // 全局异常处理
    public class GlobalExceptionHandler
    {
        public static IActionResult HandleException(Exception ex)
        {
            return new ObjectResult(ApiResponse<object>.Error(500, "服务器内部错误"))
            {
                StatusCode = 500
            };
        }
    }
}
